(()=>{'use strict';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label,cls='')=>`<a class="${cls}" href="${e(url)}" target="_blank" rel="noopener">${e(label)} ↗</a>`;
const doi=d=>d?link('https://doi.org/'+d,d):'Not assigned / not verified';
const subjectTags=d=>(d.subject_labels||[]).map(s=>`<span class="tag subject-tag">${e(s)}</span>`).join('');
const size=n=>n==null?'Not recorded':n<1000?n+' B':n<1e6?(n/1000).toFixed(1)+' kB':n<1e9?(n/1e6).toFixed(1)+' MB':(n/1e9).toFixed(2)+' GB';
function fileCard(f){const p=f.parent;return `<article class="dataset linked-file"><div><div class="overline"><span class="type">${e(f.category)} · ${e(f.kind)}</span><span>${e(f.provider)}</span></div><h3><a href="${e(f.landing)}">${e(f.name)}</a></h3><p class="file-parent">${e(p.title)}</p><div class="tags">${subjectTags(f)}<span class="tag">${e(f.format)}</span><span class="tag">${e(size(f.size_bytes))}</span>${f.run_accession?`<span class="tag">${e(f.run_accession)}</span>`:''}<span class="tag">${f.commit?'Commit '+e(f.commit.slice(0,12)):f.version===f.run_accession?'Run accession':e(f.version||'Version not documented')}</span></div></div><div class="dataset-actions">${link(f.url,f.external?'Open file':'Open local file','record-link')}<a class="record-link" href="${e(f.landing)}">File metadata →</a></div></article>`;}
function studyCard(d){return `<article class="dataset linked-study"><div><div class="overline"><span class="type">${e(d.category)} · ${d.map_points?'Reference data':'Study'}</span><span>${e(d.paper_year||'Paper not linked')}</span></div><h3><a href="${e(d.landing)}">${e(d.title)}</a></h3><p>${e(d.description)}</p><div class="tags">${subjectTags(d)}${d.source_repositories.map(s=>`<span class="tag">${e(s.provider)}</span>`).join('')}<span class="tag">${d.files.length.toLocaleString()} linked files</span>${d.categories.filter(c=>c!==d.category).map(c=>`<span class="tag">${e(c)}</span>`).join('')}</div></div><div class="dataset-actions"><span class="status">${e(d.status)}</span><a class="record-link" href="${e(d.landing)}">View study →</a><a class="record-link" href="/?content=files&kind=all&study=${e(d.id)}">Browse files →</a></div></article>`;}
function fields(entries){return `<dl class="identifier-list">${entries.map(([name,value])=>`<div><dt>${e(name)}</dt><dd>${value}</dd></div>`).join('')}</dl>`;}
function table(d){return `<div class="table-scroll"><table><thead><tr><th>Individual file</th><th>Category / role</th><th>Source</th><th>Access</th></tr></thead><tbody>${d.files.slice(0,20).map(f=>`<tr><td><a href="${e(f.landing)}">${e(f.name)}</a><small>${e(f.format)} · ${e(size(f.size_bytes))}</small></td><td>${e(f.category)}<small>${e(f.kind)}</small></td><td>${e(f.provider)}</td><td>${link(f.url,'Open file')}<small><a href="${e(f.landing)}">Metadata →</a></small></td></tr>`).join('')}</tbody></table></div><p>Showing ${Math.min(d.files.length,20)} of ${d.files.length.toLocaleString()} indexed files. <a class="record-link" href="/?content=files&kind=all&study=${e(d.id)}">Search all files in this study →</a></p>`;}
function studyDetail(d){document.title=d.title+' · CCMI Research Data';return `<div class="record-wrap"><div class="breadcrumb"><a href="/?content=studies">Study catalog</a> / ${e(d.id)}</div><div class="detail-heading"><p class="eyebrow">${e(d.category)} · ${d.map_points?'REFERENCE DATA':'LINKED STUDY'}</p><h1 class="detail-title">${e(d.title)}</h1><div class="overline"><span>${e(d.id)}</span><span>${d.files.length.toLocaleString()} individual files</span><span>${e(d.paper_year||'Paper association pending')}</span></div><p class="detail-desc">${e(d.description)}</p></div><div class="detail-grid"><div><section class="detail-section"><h2>Paper & dataset identifiers</h2>${fields([['Paper DOI',doi(d.paper_doi)],['Dataset / code-deposit DOI',doi(d.dataset_doi)],['All-versions DOI',doi(d.concept_doi)],['BioProject accession',d.repository_accession?link('https://www.ncbi.nlm.nih.gov/bioproject/'+d.repository_accession,d.repository_accession):'Not applicable'],['Paper title',e(d.paper_title)],['Paper relationship',e(d.paper_relationship_status)]])}<p>Paper and dataset DOIs identify different research outputs. A containing dataset DOI is inherited by its files as a citation relationship; individual files have not been assigned separate DOIs.</p></section><section class="detail-section" id="files"><h2>Individual data & code files</h2>${table(d)}</section><section class="detail-section"><h2>Repository metadata</h2>${fields([['Scientific subjects',e(d.subject_labels.join(', '))],['Resource types',e(d.resource_types.join(', '))],['Classification basis',e(d.subject_basis)],['Broad source categories',e(d.categories.join(', '))],['Described region',e(d.location||'Not documented')],['Spatial coverage',d.map_points?`${d.map_points.length} mapped public mooring sites · <a href="/?view=map&study=${e(d.id)}">View map →</a>`:'Not transcribed / not verified'],['Dataset creators',e(d.dataset_creators.join('; ')||'Not documented')],['Paper authors',e(d.paper_authors.join('; ')||'See paper')],['Repository licence',d.license_url?link(d.license_url,d.license):e(d.license||'Not declared / not verified')],['Metadata checked',e(d.metadata_checked)]])}<p>Licences can differ across data, code and sequencing hosts. Consult the source-licence field on each individual file.</p></section><section class="detail-section"><h2>Provenance & scope</h2><ul>${d.notes.map(n=>`<li>${e(n)}</li>`).join('')}</ul><details><summary>Repository sources and captured versions</summary><pre>${e(JSON.stringify(d.source_repositories,null,2))}</pre></details></section></div><aside><div class="download-panel"><h2>Access this study</h2><a class="btn" href="/?content=files&kind=all&study=${e(d.id)}">Browse ${d.files.length.toLocaleString()} individual files →</a>${link(d.repository_url,'Repository record','btn secondary')}${d.paper_doi?link('https://doi.org/'+d.paper_doi,'Read paper','btn secondary'):''}<a class="btn secondary" href="/metadata/${e(d.metadata)}" download>Study metadata · Markdown ↓</a><a class="file-name" href="/metadata/${e(d.id)}.json" download>JSON-LD metadata ↓</a><hr><span class="small-label">Source hosts</span>${d.source_repositories.map(s=>link(s.url,s.provider,'file-name')).join('')}<hr><span class="small-label">Inventory status</span><p>Filenames and source versions are recorded. ${d.map_points?'Original workbook and derived CSV/GeoJSON are hosted here. Coordinates were checked against the source strings; current mooring status remains unverified.':'External data stay with their original hosts; full transfers and scientific content have not been independently audited.'}</p></div></aside></div></div>`;}
function fileDetail(f,p){document.title=f.name+' · CCMI Research Data';const fullVersion=f.commit||f.version||'Not recorded';return `<div class="record-wrap"><div class="breadcrumb"><a href="/?content=files">File catalog</a> / <a href="${e(p.landing)}">${e(p.title)}</a> / File</div><div class="detail-heading"><p class="eyebrow">${e(f.category)} · ${e(f.kind)} FILE</p><h1 class="detail-title file-title">${e(f.name)}</h1><p class="detail-desc">Part of <a class="record-link" href="${e(p.landing)}">${e(p.title)} →</a></p></div><div class="detail-grid"><div><section class="detail-section"><h2>File metadata</h2>${fields([['File identifier',e(f.id)],['Scientific subjects',e(f.subject_labels.join(', '))],['Resource type',e(f.resource_types.join(', '))],['Classification basis',e(f.subject_basis)],['Broad source category',e(f.category)],['Role / format',e(f.kind+' / '+f.format)],['Host',e(f.provider)],...(f.coordinates?[['Site reference',e(f.coordinates[0]+'° N, '+Math.abs(f.coordinates[1])+'° W')],['Coordinate basis',e(f.coordinate_basis)],['Coordinate source',link(f.coordinate_source_url,f.coordinate_source||'Coordinate evidence')],['Map',`<a href="/?view=map&study=${e(p.id)}">View this series on map →</a>`]]:[]),['Size',e(size(f.size_bytes))],['Exact version',`<code>${e(fullVersion)}</code>`],['Reported checksum',f.checksum?`<code>${e(f.checksum_type)}: ${e(f.checksum)}</code>`:'Not recorded'],['Git blob SHA-1',f.git_blob_sha1?`<code>${e(f.git_blob_sha1)}</code>`:'Not applicable'],['Source licence',e(f.source_license||'Not declared / not verified')],['Metadata checked',e(f.metadata_checked)]])}</section><section class="detail-section"><h2>Related publication & dataset</h2>${fields([['Paper DOI',doi(f.paper_doi)],['Containing dataset DOI',doi(f.dataset_doi)],['All-versions DOI',doi(f.concept_doi)],['Study record',`<a href="${e(p.landing)}">${e(p.title)}</a>`],['Paper relationship',e(p.paper_relationship_status||'No associated paper recorded')]])}<p>${e(f.doi_scope)}</p></section>${f.run_accession?`<section class="detail-section"><h2>Sequencing provenance</h2>${fields([['BioProject',link('https://www.ncbi.nlm.nih.gov/bioproject/'+f.project_accession,f.project_accession)],['SRA run',link('https://www.ncbi.nlm.nih.gov/sra/'+f.run_accession,f.run_accession)],['BioSample',link('https://www.ncbi.nlm.nih.gov/biosample/'+f.sample_accession,f.sample_accession)]])}<p>${e(f.source_note)} The BioProject inventory may contain samples beyond the subset analysed in the associated paper.</p></section>`:''}<section class="detail-section"><h2>Interpretation & reuse</h2><p>Category and role are inferred from the filename and repository context. Consult the original paper, README and source metadata for units, variable definitions, sampling design, transformations and quality flags. Files are not assumed to be independent datasets merely because they have separate entries.</p><p>${e(f.link_status)}</p>${f.git_blob_sha1?'<p>A Git blob SHA-1 identifies a Git object and is not the SHA-1 or SHA-256 of the raw file bytes.</p>':''}${f.checksum_note?`<p>${e(f.checksum_note)}</p>`:''}</section></div><aside><div class="download-panel"><h2>Access this file</h2>${link(f.url,f.external?'Open original file':'Open local file','btn')}${link(f.repository_url,'View in source repository','btn secondary')}<a class="btn secondary" href="/metadata/${e(f.metadata)}" download>File metadata · Markdown ↓</a><a class="file-name" href="/metadata/${e(f.metadata_json)}" download>File metadata · JSON ↓</a><hr><a class="file-name" href="${e(p.landing)}">View parent study →</a><a class="file-name" href="/?content=files&kind=all&study=${e(p.id)}">Other files from this study →</a><p>${f.external?'This link opens the external host. Data are not copied into data.ccmi.':'This distribution is part of the private seed collection.'}</p></div></aside></div></div>`;}
function hoboDetail(d){document.title=d.title+' · CCMI Research Data';return `<div class="record-wrap"><div class="breadcrumb"><a href="/?content=studies">Data catalogue</a> / ${e(d.id)}</div><div class="detail-heading"><p class="eyebrow">ENVIRONMENTAL · HOBO LOGGER</p><h1 class="detail-title">${e(d.title)}</h1><p class="detail-desc">${e(d.description)}</p></div><div class="detail-grid"><div><section class="detail-section"><h2>Observations & instrument</h2>${fields([['Coverage',e(d.start+' – '+d.end)],['Timestamped rows',d.records.toLocaleString()],['Modal interval',e(d.interval+' minutes')],['Depth label',e(d.depth_label+' · depth in metres unknown')],['Deployment label',e(d.deployment_description)],['Logger / serial',e(d.instrument+' / '+d.serial)],['Source timezone',e(d.timezone)],['Temperature range',e(d.temperature_summary.minimum+' – '+d.temperature_summary.maximum+' °C')]])}</section><section class="detail-section"><h2>Probable location</h2><p>${e(d.coordinate_basis)}</p>${fields([['Site reference',e(d.latitude+'° N, '+Math.abs(d.longitude)+'° W')],['Coordinate scope',e(d.coordinate_scope)],['Evidence',link(d.coordinate_source_url,'NCBI BioSample SAMN55782138')]])}<a class="record-link" href="/?view=map&study=${e(d.id)}">View tentative site on map →</a></section><section class="detail-section"><h2>Data dictionary</h2><div class="table-scroll"><table><thead><tr><th>Source column</th><th>Definition</th><th>Units</th></tr></thead><tbody>${d.dictionary.map(v=>`<tr><td>${e(v.column)}</td><td>${e(v.definition)}</td><td>${e(v.unit||'—')}</td></tr>`).join('')}</tbody></table></div></section><section class="detail-section"><h2>Files & provenance</h2>${table(d)}<ul>${d.notes.map(n=>`<li>${e(n)}</li>`).join('')}</ul></section><section class="detail-section"><h2>Identifiers & reuse</h2>${fields([['Paper DOI',doi(d.paper_doi)],['Dataset DOI',doi(d.dataset_doi)],['Creators / contact','Not established'],['Licence','Not assigned'],['Quality control','Not applied']])}</section></div><aside><div class="download-panel"><h2>Explore & download</h2><a class="btn" href="/?page=explorer&site=mf">Explore MF temperature series →</a>${d.files.map(f=>link(f.url,f.provider.includes('normalized')?'Normalized observations · CSV':'Original HOBO export · CSV','btn secondary')).join('')}<a class="btn secondary" href="/metadata/${e(d.metadata)}" download>FAIR metadata · Markdown ↓</a><a class="file-name" href="/metadata/${e(d.id)}.json" download>Metadata · JSON-LD ↓</a><hr><span class="small-label">Equivalent uploads retained</span>${d.aliases.map(a=>link('/files/'+encodeURIComponent(a),a,'file-name')).join('')}</div></aside></div></div>`;}
window.LinkedCatalog={fileCard,studyCard,studyDetail,fileDetail,hoboDetail};
})();
